// Susun notifikasi error untuk admin
// 2026-08-09: + deep link ke n8n mobile dashboard supaya bisa retry dari HP
//             tanpa membuka UI n8n.
const DASH = 'https://n8n.chatminagent.workers.dev';

const e = $input.first().json;
const wfName = e.workflow?.name || 'VIRA';
const execId = e.execution?.id || '-';
const node = e.execution?.error?.node?.name || e.execution?.lastNodeExecuted || '-';
const msg = (e.execution?.error?.message || 'unknown error').substring(0, 300);
const url = e.execution?.url || '-';

// Link hanya dibuat kalau execution id benar-benar ada. Error Trigger TIDAK
// mengirim execution.id kalau errornya terjadi di node trigger — tanpa penjagaan
// ini, link-nya jadi ".../#/e/-" yang cuma bikin bingung.
const dashUrl = /^\d+$/.test(String(execId)) ? `${DASH}/#/e/${execId}` : '';

const text = `\u{1F6A8} [${wfName}] EKSEKUSI GAGAL\nNode: ${node}\nError: ${msg}\nExecution: ${execId}`
  + (dashUrl ? `\n\n\u{1F4F1} Retry dari HP:\n${dashUrl}` : '')
  + `\n\n\u{1F5A5}\uFE0F Buka di n8n:\n${url}`
  + `\n\n\u26A0\uFE0F Ada pesan user yang kemungkinan TIDAK terbalas. Cek & balas manual.`;

return [{ json: { notif_text: text } }];

// Kirimi bisa balas HTTP 200 tapi isinya gagal.
// Node ini sengaja throw supaya jalur fallback email ikut jalan.
const input = $input.first();
const r = input.json || {};

const isSuccess = r.status === true ||
                  r.success === true ||
                  (r.data && r.data.id) ||
                  (r.message && r.message !== 'error');

if (!isSuccess) {
  throw new Error('Kirimi API gagal: ' + JSON.stringify(r).slice(0, 500));
}

return [input];

// ============================================================
// Rangkai payload untuk GLOBAL - Email Fallback Notifier
// Dipanggil saat node Kirimi gagal (HTTP error ATAU response gagal)
// ============================================================

// >>> GANTI sesuai workflow: 'VIRA-PCR' atau 'VIRA-SCHOLARS' <<<
const TENANT = 'VIRA-TS';

const et = $('Error Trigger').first().json || {};
const notif = $('Compose Notif').first().json?.notif_text || '';
const f = $input.first().json || {};

// pesan kegagalan Kirimi (bentuknya beda-beda tergantung jalur error)
const reason = f.error?.message || f.error || f.message ||
               'Kirimi API tidak mengembalikan status sukses';

return [{
  json: {
    source: 'kirimi_fallback',
    tenant: TENANT,

    // isi alert yang gagal terkirim ke WA
    notif_text: notif,

    // kenapa WA-nya gagal
    fail_node: 'Notify Admin Error (Kirimi)',
    fail_reason: String(reason).slice(0, 600),
    kirimi_response: JSON.stringify(f).slice(0, 800),

    // identitas notifier ini
    notifier_wf_name: $workflow.name,
    notifier_wf_id: $workflow.id,
    notifier_exec_id: $execution.id,

    // error aslinya (dari Error Trigger)
    orig_wf_name: et.workflow?.name || '-',
    orig_wf_id: et.workflow?.id || '',
    orig_exec_id: et.execution?.id || '-',
    orig_exec_url: et.execution?.url || '',
    orig_node: et.execution?.error?.node?.name || et.execution?.lastNodeExecuted || '-',
    orig_error: String(et.execution?.error?.message || '-').slice(0, 600)
  }
}];
